mapper.select:
SELECT CAST(e.executed_at AS DATE) AS stat_date, COUNT(*) AS total, SUM(CASE WHEN e.result = 'PASS' THEN 1 ELSE 0 END) AS pass_count, SUM(CASE WHEN e.result = 'FAIL' THEN 1 ELSE 0 END) AS fail_count FROM test_execution e WHERE e.deleted = 0 AND e.executed_at IS NOT NULL
AND e.project_id = #{projectId}
AND e.executed_at >= #{startTime}
GROUP BY CAST(e.executed_at AS DATE) ORDER BY stat_date

SELECT c.priority AS name, COUNT(*) AS cnt FROM test_case c WHERE c.deleted = 0
AND c.project_id = #{projectId}
GROUP BY c.priority ORDER BY cnt DESC

SELECT c.case_type AS name, COUNT(*) AS cnt FROM test_case c WHERE c.deleted = 0
AND c.project_id = #{projectId}
GROUP BY c.case_type ORDER BY cnt DESC

SELECT d.severity AS name, COUNT(*) AS cnt FROM defect d WHERE d.deleted = 0
AND d.project_id = #{projectId}
GROUP BY d.severity ORDER BY cnt DESC

SELECT d.status AS name, COUNT(*) AS cnt FROM defect d WHERE d.deleted = 0
AND d.project_id = #{projectId}
GROUP BY d.status ORDER BY cnt DESC

SELECT p.module AS module, COUNT(DISTINCT p.id) AS point_count, COUNT(c.id) AS case_count FROM test_point p LEFT JOIN test_case c ON c.test_point_id = p.id AND c.deleted = 0 WHERE p.deleted = 0
AND p.project_id = #{projectId}
GROUP BY p.module ORDER BY point_count DESC

SELECT e.executor_name AS name, COUNT(*) AS executed, SUM(CASE WHEN e.result = 'PASS' THEN 1 ELSE 0 END) AS pass_count, SUM(CASE WHEN e.result = 'FAIL' THEN 1 ELSE 0 END) AS fail_count FROM test_execution e WHERE e.deleted = 0
AND e.project_id = #{projectId}
GROUP BY e.executor_name ORDER BY executed DESC
